const CACHE_NAME = 'apsdreamhome-v1';const STATIC_ASSETS = [ '/apsdreamhome/','/apsdreamhome/assets/css/bootstrap.min.css','/apsdreamhome/assets/js/bootstrap.bundle.min.js','/apsdreamhome/assets/fonts/fontawesome/css/all.min.css' ];self.addEventListener('install',(event)=>{event.waitUntil(caches.open(CACHE_NAME).then((cache)=>{return cache.addAll(STATIC_ASSETS);}));self.skipWaiting();});self.addEventListener('activate',(event)=>{event.waitUntil(caches.keys().then((cacheNames)=>{return Promise.all(cacheNames .filter((name)=> name !== CACHE_NAME).map((name)=> caches.delete(name)));}));self.clients.claim();});self.addEventListener('fetch',(event)=>{if(event.request.method !== 'GET')return;event.respondWith(caches.match(event.request).then((cachedResponse)=>{if(cachedResponse){event.waitUntil(fetch(event.request).then((networkResponse)=>{if(networkResponse && networkResponse.status === 200){caches.open(CACHE_NAME).then((cache)=>{cache.put(event.request,networkResponse.clone());});}}));return cachedResponse;}return fetch(event.request).then((networkResponse)=>{if(networkResponse && networkResponse.status === 200){const responseClone = networkResponse.clone();caches.open(CACHE_NAME).then((cache)=>{cache.put(event.request,responseClone);});}return networkResponse;}).catch(()=>{if(event.request.destination === 'document'){return caches.match('/apsdreamhome/');}});}));});